+type Node =
+  | { kind: "text"; value: string }
+  | { kind: "value"; path: string; escaped: boolean; position: Position }
+  | {
+      kind: "block";
+      block: "if" | "each";
+      path: string;
+      body: Node[];
+      alternate: Node[];
+      position: Position;
+    };
